-- Compatibility view of library-owned entrances. Route/scenario consumers keep
-- APR's coordinate convention while the catalogue owns geography and access.
local entranceViews = {}
local entranceViewOwners = {}

local function EntranceView(data, definition, resolved, reason, key)
    local position = resolved and resolved.position
    local source = resolved or definition
    local view = entranceViews[key]
    if not view or entranceViewOwners[key] ~= data then
        view = {}
        entranceViews[key] = view
        entranceViewOwners[key] = data
    end
    view.id, view.type = source.id, string.upper(source.kind)
    view.zone = position and position.uiMapID or (source.exterior and source.exterior.uiMapID)
    view.interiorMapIDs, view.unavailable = source.interiorMapIDs, reason
    view.requirements = source.requirements
    if position then
        local coord = view.Coord or {}
        coord.x, coord.y = position.y, position.x
        coord.mapID, coord.instanceID, coord.z = position.uiMapID, position.instanceID, position.z
        coord.accessKey, coord.noAutoconnect, coord.floor = position.accessKey, position.noAutoconnect, position.floor
        view.Coord = coord
    else
        view.Coord = nil
    end
    return view
end--[[APR_DIAG]]; EntranceView = APRTrace("APR-Core/integrations/NavigationEntrances.lua:11:EntranceView#1", EntranceView)--[[/APR_DIAG]]

function APR:GetNavigationEntranceInfo(mapID)
    local data = self.NavigationData
    if not data or not data.GetEntranceDefinitionForMap then return nil end
    local definition = data:GetEntranceDefinitionForMap(mapID)
    if not definition then return nil end
    local resolved, reason = data:GetEntranceForMap(mapID)
    return EntranceView(data, definition, resolved, reason, mapID)
end--[[APR_DIAG]]; APR.GetNavigationEntranceInfo = APRTrace("APR-Core/integrations/NavigationEntrances.lua:36:APR:GetNavigationEntranceInfo#2", APR.GetNavigationEntranceInfo)--[[/APR_DIAG]]

function APR:GetNavigationEntranceInfoForInstance(instanceID)
    local data = self.NavigationData
    if not data or not data.GetEntranceForInstance then return nil end
    local definition = data:GetEntranceDefinitionForInstance(instanceID)
    if not definition then return nil end
    local resolved, reason = data:GetEntranceForInstance(instanceID)
    return EntranceView(data, definition, resolved, reason, "instance:" .. instanceID)
end--[[APR_DIAG]]; APR.GetNavigationEntranceInfoForInstance = APRTrace("APR-Core/integrations/NavigationEntrances.lua:45:APR:GetNavigationEntranceInfoForInstance#3", APR.GetNavigationEntranceInfoForInstance)--[[/APR_DIAG]]

